#!/usr/bin/env node
/*
 * Inlines templates/workspace-*.json into main.js between the
 * BUNDLED_WORKSPACE_TEMPLATES markers.
 *
 * Why: Obsidian's plugin installer only delivers main.js / manifest.json /
 * styles.css — the templates/ folder is NOT shipped, and fs/__dirname reads
 * don't work in the plugin runtime. Bundling guarantees the workspace
 * templates (and the dashboards they define) ship with every main.js update.
 *
 * Run after editing any templates/workspace-*.json:
 *   node scripts/bundle-templates.js
 */
'use strict';
const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const templatesDir = path.join(root, 'templates');
const mainPath = path.join(root, 'main.js');

const BEGIN = '/* ===BEGIN BUNDLED_WORKSPACE_TEMPLATES (generated by scripts/bundle-templates.js — do not edit by hand) === */';
const END = '/* ===END BUNDLED_WORKSPACE_TEMPLATES=== */';

const files = fs.readdirSync(templatesDir).filter((f) => f.endsWith('.json')).sort();
const bundle = {};
for (const f of files) {
  const parsed = JSON.parse(fs.readFileSync(path.join(templatesDir, f), 'utf8'));
  bundle[f] = parsed; // validate JSON; throws on malformed
}

const main = fs.readFileSync(mainPath, 'utf8');
const begin = main.indexOf(BEGIN);
const end = main.indexOf(END);
if (begin < 0 || end < 0 || end < begin) {
  throw new Error('BUNDLED_WORKSPACE_TEMPLATES markers not found in main.js');
}

const literal = `const BUNDLED_WORKSPACE_TEMPLATES = ${JSON.stringify(bundle, null, 2)};`;
const replacement = `${BEGIN}\n${literal}\n${END}`;
const next = main.slice(0, begin) + replacement + main.slice(end + END.length);
fs.writeFileSync(mainPath, next);

const dashCounts = Object.fromEntries(
  Object.entries(bundle).map(([k, v]) => [k, Object.keys(v.dashboards || {}).length])
);
console.log(`Bundled ${files.length} template(s) into main.js:`);
console.log(files.map((f) => `  ${f} (${dashCounts[f]} dashboards)`).join('\n'));
